def is_majority(arr, n, x):
    """Check if x is the majority element in a sorted array."""
    # Find first occurrence of x
    low, high = 0, n - 1
    first = -1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == x:
            first = mid
            high = mid - 1
        elif arr[mid] < x:
            low = mid + 1
        else:
            high = mid - 1

    if first == -1:
        return False  # x not present

    # Find last occurrence of x
    low, high = 0, n - 1
    last = -1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == x:
            last = mid
            low = mid + 1
        elif arr[mid] < x:
            low = mid + 1
        else:
            high = mid - 1

    count = last - first + 1
    return count > n // 2
