from typing import List

class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        m, n = len(coins), len(coins[0])
        INF = -10**15
        # dp[i][j][k] = max profit reaching (i,j) using exactly k neutralizations
        dp = [[[INF] * 3 for _ in range(n)] for _ in range(m)]

        # Initialize start cell
        start_val = coins[0][0]
        dp[0][0][0] = start_val
        if start_val < 0:
            dp[0][0][1] = 0  # neutralize start
        # dp[0][0][2] remains INF (cannot use 2 neutralizations on one cell)

        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    continue
                for k in range(3):
                    best_same = INF
                    best_prev = INF
                    if i > 0:
                        best_same = max(best_same, dp[i-1][j][k])
                        if k > 0:
                            best_prev = max(best_prev, dp[i-1][j][k-1])
                    if j > 0:
                        best_same = max(best_same, dp[i][j-1][k])
                        if k > 0:
                            best_prev = max(best_prev, dp[i][j-1][k-1])

                    val = coins[i][j]
                    candidate = INF
                    # Option: do not neutralize this cell
                    if best_same != INF:
                        candidate = max(candidate, best_same + val)
                    # Option: neutralize this cell (use one extra neutralization)
                    if k > 0 and best_prev != INF:
                        candidate = max(candidate, best_prev)  # add 0
                    dp[i][j][k] = candidate

        return max(dp[m-1][n-1])
