from typing import List
from functools import lru_cache

class Solution:
    def minCost(self, nums: List[int]) -> int:
        n = len(nums)

        @lru_cache(None)
        def dp(i: int, mask: int) -> int:
            # mask bits: bit0 -> i+1 present, bit1 -> i+2 present
            if i >= n:
                return 0

            suffix_len = max(0, n - (i + 3))
            cnt = 1 + bin(mask).count('1') + suffix_len

            # If 2 or fewer elements remain, remove all at once
            if cnt <= 2:
                mx = nums[i]
                if mask & 1 and i + 1 < n:
                    mx = max(mx, nums[i + 1])
                if mask & 2 and i + 2 < n:
                    mx = max(mx, nums[i + 2])
                return mx

            ans = float('inf')

            # Option 1: remove i and i+1
            if mask & 1:
                cost = max(nums[i], nums[i + 1])
                new_i = i + 2
                new_mask = 0
                if i + 3 < n:
                    new_mask |= 1
                if i + 4 < n:
                    new_mask |= 2
                ans = min(ans, cost + dp(new_i, new_mask))

            # Option 2: remove i and i+2
            if mask & 2:
                cost = max(nums[i], nums[i + 2])
                new_i = i + 1
                new_mask = 0
                if i + 3 < n:
                    new_mask |= 2
                ans = min(ans, cost + dp(new_i, new_mask))

            # Option 3: remove i+1 and i+2
            if (mask & 1) and (mask & 2):
                cost = max(nums[i + 1], nums[i + 2])
                new_i = i
                new_mask = 0
                ans = min(ans, cost + dp(new_i, new_mask))

            return ans

        initial_mask = 0
        if n > 1:
            initial_mask |= 1
        if n > 2:
            initial_mask |= 2

        return dp(0, initial_mask)
