from typing import List

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        # Sort events: by timestamp, then OFFLINE before MESSAGE
        events.sort(key=lambda e: (int(e[1]), 0 if e[0] == "OFFLINE" else 1))

        online = [True] * numberOfUsers
        offline_end = [None] * numberOfUsers  # timestamp when user returns online
        mentions = [0] * numberOfUsers

        for event in events:
            t = int(event[1])
            # Process automatic comebacks before handling the event
            for i in range(numberOfUsers):
                if offline_end[i] is not None and offline_end[i] == t:
                    online[i] = True
                    offline_end[i] = None

            typ = event[0]
            if typ == "OFFLINE":
                user = int(event[2])
                online[user] = False
                offline_end[user] = t + 60
            else:  # MESSAGE
                tokens = event[2].split()
                for token in tokens:
                    if token == "ALL":
                        for i in range(numberOfUsers):
                            mentions[i] += 1
                    elif token == "HERE":
                        for i in range(numberOfUsers):
                            if online[i]:
                                mentions[i] += 1
                    else:
                        # token format: id<number>
                        num = int(token[2:])
                        mentions[num] += 1

        return mentions
