from typing import List

class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(fruits)
        if n == 0:
            return 0

        # Build segment tree for max capacity over indices
        size = 1
        while size < n:
            size <<= 1
        tree = [-10**18] * (2 * size)
        for i in range(n):
            tree[size + i] = baskets[i]
        for i in range(size - 1, 0, -1):
            tree[i] = max(tree[2 * i], tree[2 * i + 1])

        def update(pos: int):
            i = size + pos
            tree[i] = -10**18
            i //= 2
            while i:
                tree[i] = max(tree[2 * i], tree[2 * i + 1])
                i //= 2

        def query_first(x: int) -> int:
            if tree[1] < x:
                return -1
            idx = 1
            while idx < size:
                if tree[2 * idx] >= x:
                    idx = 2 * idx
                else:
                    idx = 2 * idx + 1
            return idx - size

        unplaced = 0
        for f in fruits:
            j = query_first(f)
            if j == -1:
                unplaced += 1
            else:
                update(j)
        return unplaced
