from typing import List

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        if not groups:
            return []
        max_g = max(groups)
        INF = 10**9

        # min index for each element value (only keep smallest index)
        min_idx = [INF] * (max_g + 1)
        for idx, val in enumerate(elements):
            if val <= max_g:
                if idx < min_idx[val]:
                    min_idx[val] = idx

        # best[m] = smallest index of an element that divides m
        best = [INF] * (max_g + 1)
        for v in range(1, max_g + 1):
            if min_idx[v] != INF:
                for m in range(v, max_g + 1, v):
                    if min_idx[v] < best[m]:
                        best[m] = min_idx[v]

        # Build result
        result = []
        for g in groups:
            if best[g] != INF:
                result.append(best[g])
            else:
                result.append(-1)
        return result
