    if not data:
        return
    n = int(data[0])
    A = list(map(int, data[1:1+n]))

    def can_cover(init_prev):
        # dp[cur] : possible status of edge i-1 (prev) after processing up to vertex i-1
        # At start (i=0), prev = init_prev (edge n-1)
        dp = [False, False]
        # vertex 0
        for cur in (0, 1):
            if init_prev == 1 and cur == 1:
                continue
            covered = (init_prev == 1) or (cur == 1)
            if not covered and A[0] == 0:
                continue
            dp[cur] = True

        for i in range(1, n):
            new_dp = [False, False]
            for prev in (0, 1):
                if not dp[prev]:
                    continue
                for cur in (0, 1):
                    if prev == 1 and cur == 1:
                        continue
                    covered = (prev == 1) or (cur == 1)
                    if not covered and A[i] == 0:
                        continue
                    new_dp[cur] = True
            dp = new_dp

        # After processing all vertices, dp holds possible values for edge n-1.
        # It must equal init_prev for consistency.
        return dp[init_prev]

    possible = False
    for init in (0, 1):
        if can_cover(init):
            possible = True
            break

    print("Yes" if possible else "No")

if __name__ == "__main__":
    solve()
